def pair_sum(arr, target):
    left = 0
    right = len(arr) - 1

    while left < right:
        current = arr[left] + arr[right]

        if current == target:
            return [left, right]  # found
        elif current < target:
            left += 1  # need bigger sum
        else:
            right -= 1  # need smaller sum

    return []


if __name__ == "__main__":
